feature.sample:
CFadeTransition fade;
// 暗黒から明けるフェードイン
fade.StartFade(EFadeKind::FadeIn, 0.0f, 0.5f);
// 毎フレーム:
fade.Tick(dt);
if (fade.IsMidPause()) Manager().ChangeScene<AGameplayScene>();  // 暗転中に切替
// 描画:
if (fade.IsActive()) {
    FVec3 c = fade.OverlayColor(); f32 a = fade.OverlayAlpha();
    batch.FillFullScreen(c.x, c.y, c.z, a);
}
